class Payment {void pay(double n){System.out.println("Paid (cash): Rs "+n);}} class CardPayment extends Payment {double charge(double n){return n*1.02;}void payWithProcessingFee(double n){System.out.println("Charged (card): Rs "+charge(n));}} public class CanteenPayments {static double process(Payment p,double n){if(p instanceof CardPayment){((CardPayment)p).payWithProcessingFee(n);return ((CardPayment)p).charge(n);}p.pay(n);return n;}public static void main(String[] a){System.out.println("Total: "+(process(new CardPayment(),100)+process(new Payment(),50)));}}
